const lead = $json;
const checklist = [];
if (!lead.photosAvailable) checklist.push('Send ground-level exterior photo checklist.');
if (lead.claimOpened && !lead.claimNumberAvailable) checklist.push('Ask whether claim number is available, without requesting full claim documents.');
if (!lead.adjusterAppointmentSet) checklist.push('Ask if adjuster appointment has been scheduled.');
if (lead.safePhotoReminderNeeded) checklist.push('Include safety reminder: do not climb on roof.');
return [{ json: { leadId: lead.leadId, checklist, nextAction: checklist.length ? 'Send document checklist.' : 'No document request needed today.' } }];
